package net.muxigame.minigames.horseqa;
import com.google.gson.*;
import net.muxigame.minigames.horse.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

/** Pure transactional sandbox, including genuinely concurrent callers and a separate JVM reload. */
public final class HorseMarketQA {
    private static final UUID A=UUID.fromString("1059bfa7-cc4c-4fbe-b19e-c48b9f109f15"),B=UUID.fromString("4850bffc-8d7b-4d11-b714-d772523c5221"),RACE=UUID.fromString("bd54e09a-e9b0-4e3b-8109-e12dfe579384"),RESTART_RACE=UUID.fromString("9a8c1139-a4b5-4482-a35a-dc54cc75fd72");
    private static final JsonArray checks=new JsonArray();
    private static void check(boolean pass,String label){JsonObject row=new JsonObject();row.addProperty("label",label);row.addProperty("passed",pass);checks.add(row);if(!pass)throw new AssertionError(label);}
    private static void denied(Runnable operation,String label){boolean blocked=false;try{operation.run();}catch(IllegalArgumentException|IllegalStateException expected){blocked=true;}check(blocked,label);}
    public static void main(String[] args)throws Exception{
        Path lab=Path.of(args[0]).toAbsolutePath();boolean resume=args.length>1;var config=HorseMarket.Config.preview();var offers=HorseMarket.catalog(config);boolean success=false;String error="";
        try{
            check(offers.size()==5&&offers.stream().map(HorseMarket.Offer::tier).distinct().count()==5,"five visible fixed tiers");check(offers.equals(HorseMarket.catalog(config)),"catalog traits and quotes are fixed before purchase");check(offers.getLast().rent()>config.maximumRaceReward(),"top rental costs more than all rewards in a race");denied(()->new HorseMarket.Config(10,1000,10,60),"invalid top rental reward policy rejected");
            var market=new HorseMarketSandbox(lab,config);UUID horse=offers.getLast().horse();
            if(!resume){
                market.seedMirroredPoints(A,1_000_000);market.seedMirroredPoints(B,1_000_000);long before=market.balance(A);UUID buy=UUID.randomUUID();market.buy(buy,A,horse);check(market.balance(A)==before-offers.getLast().purchase(),"purchase debits exact visible quote");market.buy(buy,A,horse);check(market.balance(A)==before-offers.getLast().purchase(),"purchase replay cannot debit twice");denied(()->market.buy(buy,B,horse),"same operation token cannot change purchaser");denied(()->market.buy(UUID.randomUUID(),B,horse),"sold horse cannot be purchased twice");
                var homebred=new HorseIdentity(UUID.randomUUID(),"Homebred fixture",.27,.95,32,false);market.registerOwnedFixture(UUID.randomUUID(),A,homebred);denied(()->market.registerOwnedFixture(UUID.randomUUID(),B,homebred),"same homebred UUID cannot be duplicated under another owner");denied(()->market.registerOwnedFixture(UUID.randomUUID(),A,new HorseIdentity(UUID.randomUUID(),"Real source denied",.25,.8,26,true)),"real horse import stays blocked pending ownership protocol");long homeBefore=market.balance(A);market.sellToPool(UUID.randomUUID(),A,homebred.horseId());check(market.balance(A)==homeBefore+HorseMarket.buyback(config,homebred),"homebred fixture sale uses actual fixed attributes");UUID homeRace=UUID.randomUUID();market.rent(UUID.randomUUID(),B,homebred.horseId(),homeRace);denied(()->market.sellToPool(UUID.randomUUID(),B,homebred.horseId()),"borrower cannot sell someone else's homebred horse");market.returnRental(UUID.randomUUID(),B,homebred.horseId(),homeRace);
                long sellBefore=market.balance(A);market.sellToPool(UUID.randomUUID(),A,horse);check(market.balance(A)==sellBefore+HorseMarket.buyback(config,offers.getLast().identity()),"sell price uses fixed horse attributes");denied(()->market.sellToPool(UUID.randomUUID(),A,horse),"sold horse cannot be sold again");
                var barrier=new CountDownLatch(1);AtomicInteger wins=new AtomicInteger(),losses=new AtomicInteger();long aBefore=market.balance(A),bBefore=market.balance(B);List<Thread> threads=new ArrayList<>();
                for(UUID player:List.of(A,B)){Thread thread=Thread.ofPlatform().start(()->{try{barrier.await();market.rent(UUID.randomUUID(),player,horse,RACE);wins.incrementAndGet();}catch(IllegalStateException expected){losses.incrementAndGet();}catch(Exception failure){throw new RuntimeException(failure);}});threads.add(thread);}barrier.countDown();for(var thread:threads)thread.join();check(wins.get()==1&&losses.get()==1,"actual concurrent rental callers produce one winner and one rejection");
                var rented=market.stock().stream().filter(s->s.offer().horse().equals(horse)).findFirst().orElseThrow();UUID renter=rented.renter();check(rented.status().equals("RENTED")&&renter!=null,"single durable rental owner");check(aBefore+bBefore-market.balance(A)-market.balance(B)==offers.getLast().rent(),"concurrent rental debits only one account once");denied(()->market.sellToPool(UUID.randomUUID(),renter,horse),"rental horse cannot be resold as owned property");denied(()->market.returnRental(UUID.randomUUID(),renter,horse,UUID.randomUUID()),"return must match actual race lease");
                UUID settlement=UUID.randomUUID();long rewardBefore=market.balance(renter);market.settle(settlement,renter,RACE,config.maximumRaceReward());market.settle(settlement,renter,RACE,config.maximumRaceReward());market.settle(UUID.randomUUID(),renter,RACE,config.maximumRaceReward());check(market.balance(renter)==rewardBefore+config.maximumRaceReward(),"same race settlement cannot reward twice, even with another operation ID");denied(()->market.settle(UUID.randomUUID(),renter,RACE,config.maximumRaceReward()-1),"conflicting settlement value rejected");denied(()->market.settle(UUID.randomUUID(),renter.equals(A)?B:A,RACE,1),"total race reward budget enforced across all recipients");check(market.balance(renter)-rewardBefore-offers.getLast().rent()<0,"top renter loses points even when winning all available rewards");
                UUID returned=UUID.randomUUID();market.returnRental(returned,renter,horse,RACE);market.returnRental(returned,renter,horse,RACE);check(market.stock().stream().filter(s->s.offer().horse().equals(horse)).findFirst().orElseThrow().status().equals("POOL"),"idempotent return releases one pool horse");
                Path blocked=market.journal().resolveSibling(market.journal().getFileName()+".tmp");Files.createDirectory(blocked);UUID retry=UUID.randomUUID(),failureRace=UUID.randomUUID();long failureBefore=market.balance(A);denied(()->market.settle(retry,A,failureRace,config.maximumRaceReward()/2),"failed atomic journal write prevents successful transaction");check(market.balance(A)==failureBefore&&new HorseMarketSandbox(lab,config).balance(A)==failureBefore,"failed persistence leaves memory and durable balance unchanged");Files.delete(blocked);market.settle(retry,A,failureRace,config.maximumRaceReward()/2);check(market.balance(A)==failureBefore+config.maximumRaceReward()/2,"same failed operation safely retries once");
                market.rent(UUID.randomUUID(),A,horse,RESTART_RACE);check(new HorseMarketSandbox(lab,config).stock().equals(market.stock()),"pending rental and visible traits survive ledger reload");JsonObject seed=new JsonObject();seed.addProperty("balanceA",market.balance(A));seed.addProperty("balanceB",market.balance(B));Files.writeString(lab.resolve("market-seed.json"),seed.toString());
            }else{
                JsonObject seed=JsonParser.parseString(Files.readString(lab.resolve("market-seed.json"))).getAsJsonObject();check(market.balance(A)==seed.get("balanceA").getAsLong()&&market.balance(B)==seed.get("balanceB").getAsLong(),"separate JVM reload preserves exact mirrored balances");var rented=market.stock().stream().filter(s->s.offer().horse().equals(horse)).findFirst().orElseThrow();check(rented.status().equals("RENTED")&&A.equals(rented.renter())&&RESTART_RACE.equals(rented.race()),"separate JVM preserves active rental identity");denied(()->market.rent(UUID.randomUUID(),B,horse,UUID.randomUUID()),"pending rental remains exclusive after JVM restart");market.returnRental(UUID.randomUUID(),A,horse,RESTART_RACE);check(market.balance(A)==seed.get("balanceA").getAsLong(),"sandbox return preserves the charged balance without inventing a refund");check(market.stock().stream().filter(s->s.offer().horse().equals(horse)).findFirst().orElseThrow().status().equals("POOL"),"restarted sandbox returns stock safely");
            }
            success=true;
        }catch(Throwable failure){error=failure.toString();}
        JsonObject report=new JsonObject();report.addProperty("success",success);report.addProperty("error",error);report.addProperty("sandboxOnly",true);report.addProperty("productionPointsTouched",false);report.add("checks",checks);Files.writeString(lab.resolve(resume?"market-resume-result.json":"market-first-result.json"),new GsonBuilder().setPrettyPrinting().create().toJson(report));System.out.println(report);if(!success)throw new IllegalStateException(error);
    }
}
